-- 07 Root Cause Analysis
WITH plant_prod AS (SELECT plant_id,AVG(JULIANDAY(actual_end)-JULIANDAY(planned_end)) AS avg_delay_days,SUM(planned_quantity-produced_quantity) AS underproduction_units FROM production_orders GROUP BY plant_id), plant_machine AS (SELECT plant_id,COUNT(*) AS machine_events,SUM(duration_minutes) AS downtime_minutes,SUM(CASE WHEN severity IN ('High','Critical') THEN 1 ELSE 0 END) AS high_severity_events FROM machine_events GROUP BY plant_id), plant_quality AS (SELECT plant_id,SUM(failed_quantity)*1.0/NULLIF(SUM(inspected_quantity),0) AS failure_rate FROM quality_inspections GROUP BY plant_id) SELECT p.plant_id,p.avg_delay_days,p.underproduction_units,m.machine_events,m.downtime_minutes,m.high_severity_events,q.failure_rate FROM plant_prod p LEFT JOIN plant_machine m USING(plant_id) LEFT JOIN plant_quality q USING(plant_id) ORDER BY p.avg_delay_days DESC;
SELECT p.plant_id,p.avg_delay_days,m.downtime_minutes,m.high_severity_events FROM (SELECT plant_id,AVG(JULIANDAY(actual_end)-JULIANDAY(planned_end)) avg_delay_days FROM production_orders GROUP BY plant_id) p JOIN (SELECT plant_id,SUM(duration_minutes) downtime_minutes,SUM(CASE WHEN severity IN ('High','Critical') THEN 1 ELSE 0 END) high_severity_events FROM machine_events GROUP BY plant_id) m USING(plant_id) ORDER BY p.avg_delay_days DESC;
SELECT q.plant_id,q.failure_rate,m.downtime_minutes,m.high_severity_events FROM (SELECT plant_id,SUM(failed_quantity)*1.0/NULLIF(SUM(inspected_quantity),0) failure_rate FROM quality_inspections GROUP BY plant_id) q JOIN (SELECT plant_id,SUM(duration_minutes) downtime_minutes,SUM(CASE WHEN severity IN ('High','Critical') THEN 1 ELSE 0 END) high_severity_events FROM machine_events GROUP BY plant_id) m USING(plant_id) ORDER BY q.failure_rate DESC;
SELECT po.supplier_id,COUNT(*) late_pos,SUM(po.quantity*po.unit_cost) late_value,AVG(pp.avg_delay_days) plant_avg_production_delay FROM purchase_orders po JOIN (SELECT plant_id,AVG(JULIANDAY(actual_end)-JULIANDAY(planned_end)) avg_delay_days FROM production_orders GROUP BY plant_id) pp USING(plant_id) WHERE po.received_date>po.promised_date GROUP BY po.supplier_id ORDER BY late_value DESC;
SELECT warehouse_id,COUNT(*) late_shipments,SUM(quantity) delayed_units,AVG(JULIANDAY(actual_delivery_date)-JULIANDAY(promised_delivery_date)) avg_delay_days FROM shipments WHERE actual_delivery_date>promised_delivery_date GROUP BY warehouse_id ORDER BY delayed_units DESC;
WITH risk AS (SELECT p.plant_id,p.avg_delay_days,m.downtime_minutes,q.failure_rate FROM (SELECT plant_id,AVG(JULIANDAY(actual_end)-JULIANDAY(planned_end)) avg_delay_days FROM production_orders GROUP BY plant_id) p JOIN (SELECT plant_id,SUM(duration_minutes) downtime_minutes FROM machine_events GROUP BY plant_id) m USING(plant_id) JOIN (SELECT plant_id,SUM(failed_quantity)*1.0/NULLIF(SUM(inspected_quantity),0) failure_rate FROM quality_inspections GROUP BY plant_id) q USING(plant_id)) SELECT *,RANK() OVER(ORDER BY avg_delay_days DESC,downtime_minutes DESC,failure_rate DESC) risk_rank FROM risk;
SELECT 'Production delay' signal,COUNT(*) affected_rows FROM production_orders WHERE actual_end>planned_end UNION ALL SELECT 'Inventory below reorder',COUNT(*) FROM inventory_snapshots WHERE on_hand_quantity<reorder_point UNION ALL SELECT 'Late shipment',COUNT(*) FROM shipments WHERE actual_delivery_date>promised_delivery_date UNION ALL SELECT 'Quality failure',SUM(failed_quantity) FROM quality_inspections;
